import{c as t,Q as n,j as o,m as a}from"./chunks/framework.BqPkuuVc.js";const m=JSON.parse('{"title":"Commentary","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/commentary.md","filePath":"user/screens/commentary.md"}'),s={name:"user/screens/commentary.md"};function r(i,e,l,h,g,c){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="commentary" tabindex="-1">Commentary <a class="header-anchor" href="#commentary" aria-label="Permalink to &quot;Commentary&quot;">​</a></h1><p><strong>Audience:</strong> Commentators and event narrators.</p><p>The <strong>Commentary</strong> view is a live feed of everything happening in the event — starts, radio-control punches, finishes, and whole classes wrapping up — written in plain language with the placing context an announcer needs. It&#39;s designed to sit on a screen in front of the commentary box and give you a running story to talk to.</p><h2 id="opening-commentary" tabindex="-1">Opening Commentary <a class="header-anchor" href="#opening-commentary" aria-label="Permalink to &quot;Opening Commentary&quot;">​</a></h2><p>On the <strong>Screens</strong> page, in the <strong>Commentary</strong> section, there are two buttons:</p><ul><li><strong>Open</strong> — opens the feed in a new browser tab.</li><li><strong>Open (with filters)</strong> — opens the same feed with the <strong>class list</strong> and <strong>filter</strong> panels showing, so you can narrow what you see.</li></ul><p>The Commentary view is its own web page (URL <code>/commentary/&lt;event-id&gt;</code>), so you can open it on a second machine the same way you&#39;d open a <a href="./creating-screens">Leaderboard screen</a>: point that device&#39;s browser at the URL. Any commentary view that&#39;s currently open is listed in the Commentary section so you can see what&#39;s connected.</p><h2 id="what-the-feed-shows" tabindex="-1">What the feed shows <a class="header-anchor" href="#what-the-feed-shows" aria-label="Permalink to &quot;What the feed shows&quot;">​</a></h2><p>Each item is timestamped and tagged by type — <strong>start</strong>, <strong>radio</strong>, <strong>finish</strong>, <strong>status</strong> (e.g. a DNF), or <strong>Class Complete</strong> when a class finishes. Items carry the competitor&#39;s name and class, the placing context (for example moving into the lead, or where a finisher slots in), and a medal (🥇🥈🥉) for the podium or a status chip for non-finishers. The newest items animate in at the top, so the feed reads as a live narrative.</p><h2 id="narrowing-the-feed-with-filters" tabindex="-1">Narrowing the feed (with filters) <a class="header-anchor" href="#narrowing-the-feed-with-filters" aria-label="Permalink to &quot;Narrowing the feed (with filters)&quot;">​</a></h2><p>Open with <strong>Open (with filters)</strong> to get two extra panels.</p><p><strong>Classes</strong> (left) lists every class with a live status at a glance:</p><ul><li>a <strong>pin</strong> to keep a class at the top,</li><li>⚡ for a class with <strong>recent activity</strong>,</li><li><strong>✓ Done</strong> when everyone&#39;s finished, or an <strong>X/Y</strong> finished-of-total count,</li><li>a green count when the <strong>top 10 places are decided</strong>.</li></ul><p>Click a class name to bring up its full results in a pop-over without leaving the feed.</p><p><strong>Filters</strong> (right) let you focus the stream:</p><ul><li><strong>Search</strong> by name or text.</li><li><strong>Classes</strong> — limit to selected classes.</li><li><strong>Item Types</strong> — toggle <strong>Starts</strong>, <strong>Radio controls</strong> (and pick which controls), <strong>Finishes</strong> (with a <strong>Placegetters only</strong> option to show just podium finishes), and <strong>Class completions</strong>.</li></ul><p>A line at the bottom shows how many of the total items are getting through the current filters, so you always know what you&#39;re looking at.</p><h2 id="tips-for-live-commentary" tabindex="-1">Tips for live commentary <a class="header-anchor" href="#tips-for-live-commentary" aria-label="Permalink to &quot;Tips for live commentary&quot;">​</a></h2><ul><li><strong>Keep it on a dedicated screen.</strong> Open it full-screen on a second monitor and let it run; it updates itself.</li><li><strong>Pin the classes you&#39;re following</strong> so the ones that matter stay at the top as the field thins out.</li><li><strong>Use it alongside the live views.</strong> Commentary gives you the running story; pair it with <a href="./../running-the-event/tracking">Tracking</a> and <a href="./../running-the-event/live-view">Live view</a> for the spatial picture of who&#39;s where on the course.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/tracking">Tracking</a> — follow competitors&#39; progress around the course</li><li><a href="./../running-the-event/live-view">Live view</a> — the live state of the event</li><li><a href="./creating-screens">Creating Leaderboard screens</a> — the arena Leaderboard displays</li></ul>',21)])])}const p=t(s,[["render",r]]);export{m as __pageData,p as default};
